import math
import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor conv2d_forward(torch::Tensor x, torch::Tensor w, c10::optional<torch::Tensor> b,
                              int stride, int padding, int dilation, int groups);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

constexpr int THREADS = 128;
constexpr int PVEC    = 4;
constexpr int MAX_OC  = 8;
constexpr int TILE_H  = 8;
constexpr int TILE_W  = 64;
__global__ void conv2d_cute_kernel(
    const float* __restrict__ X,
    const float* __restrict__ W,
    const float* __restrict__ Bias,
    float* __restrict__ Y,
    int N, int Cin, int H, int Win,
    int Cout, int K, int stride, int padding, int dilation, int groups,
    int Hout, int Wout, int OcPerBlock, int tiles_w)
{
  const int tid = threadIdx.x;
  const int n = blockIdx.z;
  const int oc_tile = blockIdx.y;
  const int oc_base = oc_tile * OcPerBlock;
  const int Cin_per_group  = Cin / groups;
  const int Cout_per_group = Cout / groups;
  const int KK = K * K;
  const int g = oc_base / Cout_per_group;
  const int ic_base = g * Cin_per_group;
  const int tile_h_idx = blockIdx.x / tiles_w;
  const int tile_w_idx = blockIdx.x - tile_h_idx * tiles_w;
  const int oh0 = tile_h_idx * TILE_H;
  const int ow0 = tile_w_idx * TILE_W;
  const int patch_h = (TILE_H - 1) * stride + dilation * (K - 1) + 1;
  const int patch_w = (TILE_W - 1) * stride + dilation * (K - 1) + 1;
  const int ih_start = oh0 * stride - padding;
  const int iw_start = ow0 * stride - padding;
  int64_t sXn = (int64_t)Cin * H * Win;
  int64_t sYn = (int64_t)Cout * Hout * Wout;
  Tensor mX = make_tensor(make_gmem_ptr(X + (int64_t)n * sXn),
                           make_shape(Cin, H, Win),
                           make_stride((int64_t)H * Win, (int64_t)Win, (int64_t)1));
  Tensor mY = make_tensor(make_gmem_ptr(Y + (int64_t)n * sYn),
                           make_shape(Cout, Hout, Wout),
                           make_stride((int64_t)Hout * Wout, (int64_t)Wout, (int64_t)1));
  Tensor mW = make_tensor(make_gmem_ptr(W),
                           make_shape(Cout, Cin_per_group * KK),
                           make_stride((int64_t)Cin_per_group * KK, (int64_t)1));
  extern __shared__ float smem_raw[];
  float* sIn = smem_raw;
  float* sWt = smem_raw + patch_h * patch_w;
  int  local_row[PVEC];
  int  local_col[PVEC];
  int  oh_arr[PVEC];
  int  ow_arr[PVEC];
  bool valid_p[PVEC];
  #pragma unroll
  for (int i = 0; i < PVEC; ++i) {
    int idx = tid + i * THREADS;
    local_row[i] = idx / TILE_W;
    local_col[i] = idx - local_row[i] * TILE_W;
    int oh = oh0 + local_row[i];
    int ow = ow0 + local_col[i];
    oh_arr[i] = oh;
    ow_arr[i] = ow;
    valid_p[i] = (oh < Hout) && (ow < Wout);
  }
  float acc[MAX_OC][PVEC];
  #pragma unroll
  for (int cc = 0; cc < MAX_OC; ++cc) {
    #pragma unroll
    for (int i = 0; i < PVEC; ++i) {
      acc[cc][i] = 0.0f;
    }
  }
  const int patch_sz = patch_h * patch_w;
  for (int ic_local = 0; ic_local < Cin_per_group; ++ic_local) {
    int ic = ic_base + ic_local;
    // Cooperative load of the (zero-padded) input patch reused by all threads/oc in this CTA
    for (int e = tid; e < patch_sz; e += THREADS) {
      int ph = e / patch_w;
      int pw = e - ph * patch_w;
      int ih = ih_start + ph;
      int iw = iw_start + pw;
      float v = 0.0f;
      if ((unsigned)ih < (unsigned)H && (unsigned)iw < (unsigned)Win) {
        v = mX(ic, ih, iw);
      }
      sIn[e] = v;
    }
    // Cooperative load of weights for this ic across all cc, kh, kw
    int wcnt = OcPerBlock * KK;
    for (int e = tid; e < wcnt; e += THREADS) {
      int cc = e / KK;
      int kk = e - cc * KK;
      int oc = oc_base + cc;
      float wv = 0.0f;
      if (oc < Cout) {
        wv = mW(oc, ic_local * KK + kk);
      }
      sWt[e] = wv;
    }
    __syncthreads();
    for (int kh = 0; kh < K; ++kh) {
      for (int kw = 0; kw < K; ++kw) {
        int kk = kh * K + kw;
        #pragma unroll
        for (int i = 0; i < PVEC; ++i) {
          if (!valid_p[i]) continue;
          int ph = local_row[i] * stride + kh * dilation;
          int pw = local_col[i] * stride + kw * dilation;
          float xval = sIn[ph * patch_w + pw];
          #pragma unroll
          for (int cc = 0; cc < MAX_OC; ++cc) {
            if (cc >= OcPerBlock) continue;
            acc[cc][i] += xval * sWt[cc * KK + kk];
          }
        }
      }
    }
    __syncthreads();
  }
  #pragma unroll
  for (int cc = 0; cc < MAX_OC; ++cc) {
    if (cc >= OcPerBlock) continue;
    int oc = oc_base + cc;
    if (oc >= Cout) continue;
    float bval = (Bias != nullptr) ? Bias[oc] : 0.0f;
    #pragma unroll
    for (int i = 0; i < PVEC; ++i) {
      if (!valid_p[i]) continue;
      mY(oc, oh_arr[i], ow_arr[i]) = acc[cc][i] + bval;
    }
  }
}
torch::Tensor conv2d_forward(torch::Tensor x, torch::Tensor w, c10::optional<torch::Tensor> b,
                              int stride, int padding, int dilation, int groups) {
  TORCH_CHECK(x.is_cuda() && w.is_cuda(), "x and w must be CUDA tensors");
  TORCH_CHECK(x.scalar_type() == at::kFloat && w.scalar_type() == at::kFloat, "float32 only");
  TORCH_CHECK(x.dim() == 4 && w.dim() == 4, "x and w must be 4D");
  int N   = (int)x.size(0);
  int Cin = (int)x.size(1);
  int H   = (int)x.size(2);
  int Win = (int)x.size(3);
  int Cout = (int)w.size(0);
  int Cin_per_group = (int)w.size(1);
  int K = (int)w.size(2);
  TORCH_CHECK((int)w.size(3) == K, "kernel must be square");
  TORCH_CHECK(Cin_per_group * groups == Cin, "channel/groups mismatch");
  int Hout = (H + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
  int Wout = (Win + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
  TORCH_CHECK(Hout > 0 && Wout > 0, "invalid output size");
  auto x_c = x.contiguous();
  auto w_c = w.contiguous();
  const float* bias_ptr = nullptr;
  torch::Tensor b_c;
  if (b.has_value() && b.value().defined()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && (int)b_c.size(0) == Cout, "bias shape mismatch");
    bias_ptr = b_c.data_ptr<float>();
  }
  auto y = torch::empty({N, Cout, Hout, Wout}, x.options());
  int Cout_per_group = Cout / groups;
  int OcPerBlock = 1;
  int candidates[4] = {8, 4, 2, 1};
  for (int i = 0; i < 4; ++i) {
    if (Cout_per_group % candidates[i] == 0) { OcPerBlock = candidates[i]; break; }
  }
  int tiles_h = (Hout + TILE_H - 1) / TILE_H;
  int tiles_w = (Wout + TILE_W - 1) / TILE_W;
  dim3 block(THREADS);
  dim3 grid((unsigned)(tiles_h * tiles_w),
             (unsigned)((Cout + OcPerBlock - 1) / OcPerBlock),
             (unsigned)N);
  int patch_h = (TILE_H - 1) * stride + dilation * (K - 1) + 1;
  int patch_w = (TILE_W - 1) * stride + dilation * (K - 1) + 1;
  size_t smem_bytes = (size_t)(patch_h * patch_w + OcPerBlock * K * K) * sizeof(float);
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  conv2d_cute_kernel<<<grid, block, smem_bytes, stream>>>(
      x_c.data_ptr<float>(), w_c.data_ptr<float>(), bias_ptr, y.data_ptr<float>(),
      N, Cin, H, Win, Cout, K, stride, padding, dilation, groups, Hout, Wout, OcPerBlock, tiles_w);
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv2d_cute_kernel launch failed: ", cudaGetErrorString(err));
  return y;
}
"""

conv2d_ext = load_inline(
    name="cute_conv2d_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["conv2d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/root/cutegen_test/cutegen/cutlass/include",
        "/root/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Standard 2D convolution implemented with a custom cooperative-tiled CUTE/CUDA kernel.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, dilation: int = 1,
                 groups: int = 1, bias: bool = False) -> None:
        super().__init__()
        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = int(kernel_size)
        self.stride = int(stride)
        self.padding = int(padding)
        self.dilation = int(dilation)
        self.groups = int(groups)

        assert self.in_channels % self.groups == 0
        assert self.out_channels % self.groups == 0

        self.weight = nn.Parameter(
            torch.empty(self.out_channels, self.in_channels // self.groups,
                        self.kernel_size, self.kernel_size)
        )
        if bias:
            self.bias = nn.Parameter(torch.empty(self.out_channels))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()
        self._ext = conv2d_ext

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = (self.in_channels // self.groups) * self.kernel_size * self.kernel_size
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.conv2d_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias if self.bias is not None else None,
            int(self.stride),
            int(self.padding),
            int(self.dilation),
            int(self.groups),
        )

