  Tensor mW = make_tensor(make_gmem_ptr(W),
                           make_shape(Cout, R),
                           make_stride((int64_t)R, (int64_t)1));

  extern __shared__ float smem_raw[];
  Tensor sW = make_tensor(make_smem_ptr(smem_raw),
                           make_shape(OcPerBlock, Int<RCHUNK>{}),
                           make_stride(Int<RCHUNK>{}, Int<1>{}));

  int  p_idx[PVEC];
  int  oh_arr[PVEC];
  int  ow_arr[PVEC];
  bool valid_p[PVEC];

