  for (int i = 0; i < PVEC; ++i) {
    int p = p_block + tid + i * THREADS;
    p_idx[i] = p;
    if (p < P_total) {
      oh_arr[i] = p / Wout;
      ow_arr[i] = p - oh_arr[i] * Wout;
      valid_p[i] = true;
    } else {
      oh_arr[i] = 0; ow_arr[i] = 0; valid_p[i] = false;
    }
