  #pragma unroll
  for (int cc = 0; cc < MAX_OC; ++cc) {
    #pragma unroll
    for (int i = 0; i < PVEC; ++i) {
      acc[cc][i] = 0.0f;
    }
  }

  for (int r0 = 0; r0 < R; r0 += RCHUNK) {
    // Load weight chunk into shared memory
    for (int kk = tid; kk < RCHUNK; kk += THREADS) {
      int r_global = r0 + kk;
      #pragma unroll
      for (int cc = 0; cc < MAX_OC; ++cc) {
        if (cc >= OcPerBlock) continue;
        int oc = oc_base + cc;
        float wval = 0.0f;
        if (oc < Cout && r_global < R) {
