        int iw = ow_arr[i] * stride - padding + kw * dilation;
        if ((unsigned)ih >= (unsigned)H || (unsigned)iw >= (unsigned)Win) continue;
        float xval = mX(ic, ih, iw);
        #pragma unroll
        for (int cc = 0; cc < MAX_OC; ++cc) {
          if (cc >= OcPerBlock) continue;
          acc[cc][i] += xval * sW(cc, kk);
        }
      }
    }
    __syncthreads();
  }

  #pragma unroll
  for (int cc = 0; cc < MAX_OC; ++cc) {
    if (cc >= OcPerBlock) continue;
    int oc = oc_base + cc;
    if (oc >= Cout) continue;
    float bval = (Bias != nullptr) ? Bias[oc] : 0.0f;
    #pragma unroll
    for (int i = 0; i < PVEC; ++i) {
      if (!valid_p[i]) continue;
